export default function HeroSection() {
  return (
    <Box
      sx={{
        position: 'relative',
        bgcolor: 'background.default',
        overflow: 'hidden',
        py: { xs: 10, md: 14 },
        '&::before': {
          content: '""',
          position: 'absolute',
          top: '-30%',
          right: '-10%',
          width: '600px',
          height: '600px',
          borderRadius: '50%',
          background: 'radial-gradient(circle, rgba(76,175,80,0.12) 0%, transparent 70%)',
          pointerEvents: 'none',
        },
      }}
    >
      <Container maxWidth="lg">
        <Box sx={{ display: 'flex', flexDirection: { xs: 'column', md: 'row' }, alignItems: 'center', gap: { xs: 4, md: 3, lg: 6 } }}>

          {/* ── Text content ── */}
          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography
              variant="overline"
              sx={{ color: 'primary.main', fontWeight: 700, letterSpacing: '0.15em', mb: 2, display: 'block' }}
            >
              Minneapolis · Twin Cities
            </Typography>
            <Typography
              variant="h1"
              sx={{
                fontSize: 'clamp(2.2rem, 6vw, 4.2rem)',
                lineHeight: 1.05,
                mb: 3,
                color: 'white',
              }}
            >
              Where Fútbol
              <Box component="span" sx={{ color: 'primary.main' }}> Lives</Box>
            </Typography>

            <Typography
              variant="body1"
              sx={{ fontSize: { xs: '1rem', md: '1.1rem' }, color: 'text.secondary', mb: 5, maxWidth: 520, lineHeight: 1.7 }}
            >
              A community built for fútbol lovers of the diaspora. Come through for FIFA sessions,
              tournaments, watch parties, and the culture — right here in the Twin Cities.
            </Typography>

            <Stack direction={{ xs: 'column', sm: 'row' }} gap={2}>
              <Button
                component={Link}
                to="/tournaments"
                variant="contained"
                color="primary"
                size="large"
                startIcon={<EmojiEventsIcon />}
                sx={{ px: 4, py: 1.5, fontSize: '1rem' }}
              >
                View Tournaments
              </Button>
              <Button
                component={Link}
                to="/community"
                variant="outlined"
                color="primary"
                size="large"
                startIcon={<GroupsIcon />}
                sx={{ px: 4, py: 1.5, fontSize: '1rem' }}
              >
                Join the Community
              </Button>
            </Stack>
          </Box>

          {/* ── Player illustration ── */}
          <Box
            sx={{
              flexShrink: 0,
              width: { xs: 220, sm: 280, md: 340, lg: 420 },
              opacity: 0.88,
              order: { xs: -1, md: 0 },
            }}
          >
            <PlayerIllustration />
          </Box>

        </Box>
      </Container>
    </Box>
  )
}
